create table if not exists public.asset_category(category_id bigint generated always as identity primary key,category_name text not null unique,useful_life_months integer not null check(useful_life_months>0),depreciation_method text not null,asset_account_id bigint not null references public.chart_accounts(account_id),depreciation_account_id bigint not null references public.chart_accounts(account_id),check(asset_account_id<>depreciation_account_id));
create table if not exists public.asset(asset_id bigint generated always as identity primary key,asset_number text not null unique,asset_name text not null,category_id bigint not null references public.asset_category(category_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),location_id bigint not null references public.locations(location_id),currency_id bigint not null references public.currencies(currency_id),purchase_date date not null,purchase_cost numeric(24,6) not null check(purchase_cost>=0));
create table if not exists public.asset_depreciation(depreciation_id bigint generated always as identity primary key,depreciation_date date not null,asset_id bigint not null references public.asset(asset_id),fiscal_period_id bigint not null references public.fiscal_periods(fiscal_period_id),gl_impact_id bigint references public.gl_impact(gl_impact_id) on delete set null,depreciation_amount numeric(24,6) not null check(depreciation_amount>=0),accumulated_depreciation numeric(24,6) not null check(accumulated_depreciation>=0),unique(asset_id,fiscal_period_id));
create table if not exists public.asset_transfer(transfer_id bigint generated always as identity primary key,transfer_date date not null,asset_id bigint not null references public.asset(asset_id),source_subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),target_subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),check(source_subsidiary_id<>target_subsidiary_id));
create table if not exists public.asset_disposal(disposal_id bigint generated always as identity primary key,disposal_date date not null,asset_id bigint not null references public.asset(asset_id),transaction_id bigint references public."transaction"(transaction_id) on delete set null,disposal_type text not null,sale_amount numeric(24,6) not null default 0 check(sale_amount>=0),gain_loss_amount numeric(24,6) not null default 0);
create table if not exists public.asset_maintenance(maintenance_id bigint generated always as identity primary key,maintenance_date date not null,asset_id bigint not null references public.asset(asset_id),description text not null,cost numeric(24,6) not null check(cost>=0),supplier_id bigint references public.suppliers(supplier_id));
do $$declare t text;begin foreach t in array array['asset_category','asset','asset_depreciation','asset_transfer','asset_disposal','asset_maintenance'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "fixed_assets_select" on public.%I',t);execute format('drop policy if exists "fixed_assets_insert" on public.%I',t);execute format('drop policy if exists "fixed_assets_update" on public.%I',t);execute format('drop policy if exists "fixed_assets_delete" on public.%I',t);execute format('create policy "fixed_assets_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "fixed_assets_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "fixed_assets_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "fixed_assets_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
